#!/usr/bin/env bash
set -euo pipefail
mkdir -p non-secure url-alphabet bin
mkdir -p $(dirname package.json)
printf '%s' '' | base64 -d > package.json
mkdir -p $(dirname package-lock.json)
printf '%s' '' | base64 -d > package-lock.json
mkdir -p $(dirname index.js)
printf '%s' '' | base64 -d > index.js
mkdir -p $(dirname index.browser.js)
printf '%s' '' | base64 -d > index.browser.js
mkdir -p $(dirname index.d.ts)
printf '%s' '' | base64 -d > index.d.ts
mkdir -p $(dirname non-secure/index.js)
printf '%s' '' | base64 -d > non-secure/index.js
mkdir -p $(dirname non-secure/index.d.ts)
printf '%s' '' | base64 -d > non-secure/index.d.ts
mkdir -p $(dirname url-alphabet/index.js)
printf '%s' '' | base64 -d > url-alphabet/index.js
mkdir -p $(dirname bin/nanoid.js)
printf '%s' '' | base64 -d > bin/nanoid.js
chmod 0555 bin/nanoid.js
